"use client";

// Generated by philote from component HorseView's actions. Do not edit.
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useState, useTransition } from "react";

import { toast } from "sonner";

import { remove } from "@/lib/actions/horse-view";
import { cn } from "@/lib/utils";

import { Button, buttonVariants } from "@/components/ui/button";

export default function HorseViewActions({ id }: { id: string }) {
    const router = useRouter();
    const [pending, start] = useTransition();
    // A delete asks on the page, not in a browser dialog, so the question
    // looks like the app and sits next to the button it's about.
    const [confirming, setConfirming] = useState(false);
    return (
        <div className="flex flex-wrap gap-2">
            <Link href={`/horses/${encodeURIComponent(id)}/edit`} className={cn(buttonVariants({ variant: "outline", size: "sm" }))}>
                {"Edit Horse"}
            </Link>
            {confirming ? (
                <>
                    <span className="self-center text-sm text-muted-foreground">{"Delete this horse?"}</span>
                    <Button
                        variant="destructive"
                        size="sm"
                        disabled={pending}
                        onClick={() => {
                            start(async () => {
                                const error = await remove(id);
                                if (error) {
                                    toast.error(error);
                                    setConfirming(false);
                                } else {
                                    router.refresh();
                                }
                            });
                        }}
                    >
                        {"Delete"}
                    </Button>
                    <Button variant="ghost" size="sm" disabled={pending} onClick={() => setConfirming(false)}>
                        Cancel
                    </Button>
                </>
            ) : (
                <Button variant="destructive" size="sm" onClick={() => setConfirming(true)}>
                    {"Delete"}
                </Button>
            )}
        </div>
    );
}
